'use strict';
const {t}=window.PortfolioI18n;
const el=id=>document.getElementById(id),categories={landscape:'自然風景',architecture:'建築線條',street:'城市片刻'};
let authenticationLost=false;
let photos=[],coverId=null,view='all',editingId=null,lastEditorTrigger=null,baseline='',saving=false,uploading=false,reordering=false,orderSnapshot=[],dragId=null;
function node(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;}
function requireLogin(){if(authenticationLost)return;authenticationLost=true;photos=[];coverId=null;el('studio-content').hidden=true;el('photo-grid').replaceChildren();for(const id of ['editor','delete-dialog'])if(el(id).open)el(id).close();el('edit-image').removeAttribute('src');el('account').textContent=t('請重新登入');el('logout').hidden=true;status(t('登入已失效，請重新登入後繼續管理作品。'),true);const link=node('a','button primary',t('重新登入'));link.href='/login?expired=1';link.target='_top';el('load-state').replaceChildren(link);el('load-state').hidden=false;}
async function api(path,method='GET',body){let response;try{response=await fetch(path,{method,credentials:'same-origin',headers:{'X-Portfolio-Admin':'1',...(body!==undefined?{'Content-Type':'application/json'}:{})},body:body===undefined?undefined:JSON.stringify(body)});}catch{throw new Error(t('無法連線，請檢查網路後重試。'));}if(response.status===401||response.redirected){requireLogin();throw new Error(t('請重新登入後繼續操作。'));}let data;try{data=await response.json();}catch{throw new Error(t('登入可能已過期，請重新登入後重試。'));}if(!response.ok)throw new Error(t(data.error)||t('操作無法完成，請稍後重試。'));return data;}
function status(message,error=false){const n=el('status');n.replaceChildren(node('span','',message));const b=node('button','',t('關閉'));b.type='button';b.addEventListener('click',()=>n.hidden=true);n.append(b);n.classList.toggle('error',error);n.hidden=false;}
function updateSummary(){el('total-count').textContent=photos.length;el('published-count').textContent=photos.filter(p=>p.published).length;el('draft-count').textContent=photos.filter(p=>!p.published).length;const cover=photos.find(p=>p.id===coverId);el('cover-summary').textContent=t('首頁封面：')+(cover?cover.title:t('自動選取'));}
function displayedPhotos(){const search=el('search').value.trim().toLowerCase();return photos.filter(p=>(view==='all'||(view==='published'?p.published:!p.published))&&(!search||(p.title+' '+p.location+' '+p.description+' '+p.titleEn+' '+p.locationEn+' '+p.descriptionEn).toLowerCase().includes(search)));}
function render(){updateSummary();const shown=displayedPhotos(),grid=el('photo-grid');grid.replaceChildren();el('empty-state').hidden=photos.length>0;el('no-results').hidden=!photos.length||shown.length>0;el('reorder-toggle').disabled=photos.length<2||uploading;el('reorder-toggle').hidden=reordering;el('reorder-notice').hidden=!reordering;
 for(const p of shown){
  const card=node('article','artwork');card.dataset.id=p.id;card.draggable=reordering;
  const imageBox=node('div','artwork-image'),imageButton=node('button');imageButton.type='button';imageButton.setAttribute('aria-label',t('編輯作品：')+p.title);imageButton.disabled=reordering;const img=node('img');img.src=p.thumbnail;img.alt=p.title;img.loading='lazy';imageButton.append(img);imageButton.addEventListener('click',()=>openEditor(p.id,imageButton));imageBox.append(imageButton,node('span','status-badge'+(p.published?' published':''),p.published?t('已公開'):t('草稿')));if(p.id===coverId)imageBox.append(node('span','cover-badge',t('首頁封面')));card.append(imageBox);
  const info=node('div','artwork-info');info.append(node('h3','',p.title),node('p','artwork-meta',t(categories[p.category])+' · '+(p.width||0)+' × '+(p.height||0)));
  const actions=node('div','artwork-actions');const edit=node('button','',t('編輯作品'));edit.type='button';edit.disabled=reordering;edit.addEventListener('click',()=>openEditor(p.id,edit));actions.append(edit);
  if(p.published){const cover=node('button','',p.id===coverId?t('取消首頁封面'):t('設為首頁封面'));cover.type='button';cover.disabled=reordering;cover.addEventListener('click',async()=>{cover.disabled=true;try{const data=await api('/api/admin/cover','PUT',{id:p.id===coverId?null:p.id});coverId=data.coverId;render();status(t('首頁封面已更新。'));}catch(e){status(t(e.message),true);cover.disabled=false;}});actions.append(cover);}else actions.append(node('span','artwork-meta',t('尚未公開')));
  info.append(actions);card.append(info);
  if(reordering){const controls=node('div','reorder-buttons');for(const [delta,title]of[[-1,t('向前移動')],[1,t('向後移動')]]){const b=node('button','',title);b.type='button';const index=photos.findIndex(x=>x.id===p.id);b.disabled=delta<0?index===0:index===photos.length-1;b.addEventListener('click',()=>movePhoto(p.id,delta));controls.append(b);}card.append(controls);card.addEventListener('dragstart',e=>{dragId=p.id;e.dataTransfer.setData('text/plain',p.id);e.dataTransfer.effectAllowed='move';card.classList.add('dragging');});card.addEventListener('dragend',()=>{dragId=null;grid.querySelectorAll('.dragging,.drag-target').forEach(n=>n.classList.remove('dragging','drag-target'));});card.addEventListener('dragover',e=>{if(dragId&&dragId!==p.id){e.preventDefault();e.dataTransfer.dropEffect='move';card.classList.add('drag-target');}});card.addEventListener('dragleave',()=>card.classList.remove('drag-target'));card.addEventListener('drop',e=>{e.preventDefault();if(!dragId||dragId===p.id)return;const from=photos.findIndex(x=>x.id===dragId),to=photos.findIndex(x=>x.id===p.id);if(from<0||to<0)return;photos.splice(to,0,photos.splice(from,1)[0]);dragId=null;render();});}
  grid.append(card);
 }
}
async function loadPhotos(){const data=await api('/api/admin/photos');photos=data.photos;coverId=data.coverId;render();}
function editorValues(){return{title:el('edit-title').value,titleEn:el('edit-title-en').value,locationEn:el('edit-location-en').value,descriptionEn:el('edit-description-en').value,category:el('edit-category').value,description:el('edit-description').value,location:el('edit-location').value,takenAt:el('edit-date').value,published:el('edit-published').checked};}
function dirty(){return editingId!==null&&JSON.stringify(editorValues())!==baseline;}
function openEditor(id,trigger){const p=photos.find(p=>p.id===id);if(!p)return;editingId=id;lastEditorTrigger=trigger;el('edit-image').src=p.large;el('edit-image').alt=p.title;el('edit-title').value=p.title;el('edit-title-en').value=p.titleEn||'';el('edit-location-en').value=p.locationEn||'';el('edit-description-en').value=p.descriptionEn||'';el('edit-category').value=p.category;el('edit-description').value=p.description;el('edit-location').value=p.location;el('edit-date').value=p.takenAt;el('edit-published').checked=p.published;el('edit-meta').textContent=`${p.width} × ${p.height} · ${(p.bytes/1024/1024).toFixed(1)} MB`;el('editor-error').hidden=true;baseline=JSON.stringify(editorValues());el('editor').showModal();document.body.classList.add('dialog-open');el('edit-title').focus();}
function closeEditor(){if(saving)return;if(dirty()&&!confirm(t('尚有未儲存的變更，要放棄這次編輯嗎？')))return;el('editor').close();}
el('close-editor').addEventListener('click',closeEditor);el('cancel-edit').addEventListener('click',closeEditor);el('editor').addEventListener('cancel',e=>{e.preventDefault();closeEditor();});el('editor').addEventListener('close',()=>{editingId=null;document.body.classList.remove('dialog-open');lastEditorTrigger?.focus();});
function editorBusy(busy){saving=busy;for(const id of['save-photo','delete-photo','cancel-edit','close-editor'])el(id).disabled=busy;el('save-photo').textContent=busy?t('正在儲存…'):t('儲存變更');}
el('edit-form').addEventListener('submit',async e=>{e.preventDefault();if(saving)return;const p=photos.find(p=>p.id===editingId);if(!p)return;editorBusy(true);el('editor-error').hidden=true;try{const data=await api('/api/admin/photos/'+p.id,'PATCH',{...editorValues(),version:p.version});photos[photos.findIndex(x=>x.id===p.id)]=data.photo;if(!data.photo.published&&coverId===p.id)coverId=null;baseline=JSON.stringify(editorValues());el('editor').close();render();status(data.photo.published?t('作品已儲存並公開。'):t('作品已儲存為草稿。'));}catch(error){el('editor-error').textContent=t(error.message);el('editor-error').hidden=false;}finally{editorBusy(false);}});
el('delete-photo').addEventListener('click',()=>{const p=photos.find(p=>p.id===editingId);if(!p)return;el('delete-title').textContent='「'+p.title+'」';el('delete-error').hidden=true;el('delete-dialog').showModal();});el('cancel-delete').addEventListener('click',()=>el('delete-dialog').close());
el('confirm-delete').addEventListener('click',async()=>{const p=photos.find(p=>p.id===editingId);if(!p)return;el('confirm-delete').disabled=true;el('cancel-delete').disabled=true;el('delete-error').hidden=true;try{await api('/api/admin/photos/'+p.id,'DELETE',{version:p.version});photos=photos.filter(x=>x.id!==p.id);if(coverId===p.id)coverId=null;el('delete-dialog').close();baseline=JSON.stringify(editorValues());el('editor').close();render();status(t('作品已刪除。'));}catch(e){el('delete-error').textContent=t(e.message);el('delete-error').hidden=false;}finally{el('confirm-delete').disabled=false;el('cancel-delete').disabled=false;}});el('delete-dialog').addEventListener('cancel',e=>{if(el('confirm-delete').disabled)e.preventDefault();});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{if(reordering)return;view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});render();}));el('search').addEventListener('input',render);
function setReordering(value){reordering=value;for(const b of document.querySelectorAll('[data-view]'))b.disabled=value;el('search').disabled=value;el('refresh').disabled=value||uploading;el('select-files').disabled=value||uploading;el('upload-category').disabled=value||uploading;render();}
el('reorder-toggle').addEventListener('click',()=>{orderSnapshot=photos.map(p=>p.id);view='all';el('search').value='';document.querySelectorAll('[data-view]').forEach(b=>{const a=b.dataset.view==='all';b.classList.toggle('active',a);b.setAttribute('aria-pressed',String(a));});setReordering(true);});
function movePhoto(id,delta){const i=photos.findIndex(x=>x.id===id),j=i+delta;if(j<0||j>=photos.length)return;[photos[i],photos[j]]=[photos[j],photos[i]];render();}
el('cancel-order').addEventListener('click',()=>{const lookup=new Map(photos.map(p=>[p.id,p]));photos=orderSnapshot.map(id=>lookup.get(id)).filter(Boolean);setReordering(false);});
el('save-order').addEventListener('click',async()=>{el('save-order').disabled=true;el('cancel-order').disabled=true;try{await api('/api/admin/reorder','POST',{ids:photos.map(p=>p.id)});setReordering(false);status(t('作品排序已儲存。'));}catch(e){status(t(e.message),true);}finally{el('save-order').disabled=false;el('cancel-order').disabled=false;}});
el('refresh').addEventListener('click',async()=>{el('refresh').disabled=true;try{await loadPhotos();status(t('作品清單已重新載入。'));}catch(e){status(t(e.message),true);}finally{el('refresh').disabled=false;}});
function chooseFiles(){if(!uploading&&!reordering)el('file-input').click();}el('select-files').addEventListener('click',chooseFiles);el('empty-upload').addEventListener('click',chooseFiles);
el('file-input').addEventListener('change',()=>{const files=[...el('file-input').files];el('file-input').value='';if(files.length)uploadFiles(files);});
let dragDepth=0;el('drop-zone').addEventListener('dragenter',e=>{e.preventDefault();dragDepth++;if(!uploading&&!reordering)el('drop-zone').classList.add('drag-over');});el('drop-zone').addEventListener('dragover',e=>e.preventDefault());el('drop-zone').addEventListener('dragleave',e=>{e.preventDefault();dragDepth--;if(dragDepth<=0)el('drop-zone').classList.remove('drag-over');});el('drop-zone').addEventListener('drop',e=>{e.preventDefault();dragDepth=0;el('drop-zone').classList.remove('drag-over');if(uploading||reordering){status(t('請先完成目前的上傳或排序。'),true);return;}uploadFiles([...e.dataTransfer.files]);});
async function derivative(bitmap,size){const ratio=Math.min(1,size/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.88));canvas.width=canvas.height=1;if(!blob)throw new Error(t('無法產生預覽照片。'));return blob;}
async function uploadOne(file,category,onProgress){if(file.size>15*1024*1024)throw new Error(t('檔案超過 15 MB，請先匯出較小的照片。'));if(file.type&&!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error(t('僅支援 JPG、PNG 與 WebP。'));let bitmap;try{bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});}catch{throw new Error(t('照片無法讀取，請確認檔案格式。'));}let thumbnail,large,width=bitmap.width,height=bitmap.height;try{thumbnail=await derivative(bitmap,800);large=await derivative(bitmap,1800);}finally{bitmap.close();}const form=new FormData();form.append('original',file);form.append('thumbnail',thumbnail,'thumbnail.jpg');form.append('large',large,'large.jpg');form.append('title',file.name.replace(/\.[^.]+$/,'').slice(0,120)||t('未命名作品'));form.append('category',category);form.append('width',width);form.append('height',height);return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/admin/photos');xhr.setRequestHeader('X-Portfolio-Admin','1');xhr.timeout=180000;xhr.upload.onprogress=e=>{if(e.lengthComputable)onProgress(e.loaded/e.total);};xhr.onerror=()=>reject(new Error(t('上傳中斷，請檢查網路後重試。')));xhr.ontimeout=()=>reject(new Error(t('上傳逾時，請先重新載入作品確認結果，再重試。')));xhr.onload=()=>{if(xhr.status===401||new URL(xhr.responseURL||location.href).pathname.startsWith('/cdn-cgi/')||new URL(xhr.responseURL||location.href).pathname==='/login'){requireLogin();reject(new Error(t('登入已失效，請重新登入後再上傳。')));return;}let data;try{data=JSON.parse(xhr.responseText);}catch{reject(new Error(t('登入可能已過期，請重新登入。')));return;}if(xhr.status>=200&&xhr.status<300)resolve(data.photo);else reject(new Error(t(data.error)||t('上傳失敗，請稍後重試。')));};xhr.send(form);});}
async function uploadFiles(files){if(uploading||reordering||!files.length)return;uploading=true;el('select-files').disabled=true;el('upload-category').disabled=true;el('refresh').disabled=true;el('reorder-toggle').disabled=true;el('upload-progress').hidden=false;el('upload-results').replaceChildren();const category=el('upload-category').value;let count=0;const failed=[];try{for(let i=0;i<files.length;i++){if(authenticationLost)break;const file=files[i];el('progress').value=i/files.length*100;el('progress-label').textContent=`${i+1} / ${files.length} · ${t('正在處理 {name}',{name:file.name})}`;try{const photo=await uploadOne(file,category,ratio=>{el('progress').value=(i+ratio)/files.length*100;el('progress-label').textContent=`${i+1} / ${files.length} · ${file.name} · ${Math.round(ratio*100)}%`;});photos.push(photo);count++;render();}catch(e){failed.push(file);el('upload-results').append(node('p','failure',file.name+'：'+e.message));}}el('progress').value=100;el('progress-label').textContent=t('上傳完成：{count} 張已儲存為草稿，{failed} 張未完成。',{count,failed:failed.length});if(failed.length){const retry=node('button','button',t('重試未完成的照片'));retry.type='button';retry.addEventListener('click',()=>uploadFiles(failed));el('upload-results').append(retry);}if(count)status(t('照片已儲存。點選「編輯作品」整理內容，再勾選公開。'));}finally{uploading=false;el('select-files').disabled=false;el('upload-category').disabled=false;el('refresh').disabled=false;render();}}
window.addEventListener('beforeunload',e=>{if(uploading||dirty()||(reordering&&photos.map(p=>p.id).join()!==orderSnapshot.join())){e.preventDefault();e.returnValue='';}});
async function initialize(){try{const session=await api('/api/admin/session');const data=await api('/api/admin/photos');el('account').textContent=session.email;el('logout').href=session.logoutUrl;el('logout').hidden=false;photos=data.photos;coverId=data.coverId;el('studio-content').hidden=false;render();}catch(e){if(authenticationLost)return;el('account').textContent=t('無法載入作品');status(t(e.message),true);const retry=node('button','button',t('重新載入'));retry.type='button';retry.addEventListener('click',()=>location.reload());el('load-state').replaceChildren(retry);return;}el('load-state').hidden=true;}
window.addEventListener('portfolio-languagechange',()=>{render();editorBusy(saving);window.PortfolioI18n.refreshMessages(['status','account','load-state','editor-error','delete-error','progress-label','upload-results']);});
initialize();
